import { Component, computed, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { CatalogService, OrderService } from '../../core/services/domain.services';
import { ToastService } from '../../core/services/toast.service';
import { Category, FoodItem, Order } from '../../core/models/models';
import { IconComponent } from '../../shared/icon/icon.component';
import { MoneyPipe } from '../../shared/pipes/money.pipe';
import { LoadingComponent, EmptyStateComponent, SpinnerComponent } from '../../shared/ui/misc';
import { ReceiptDialogComponent } from '../orders/receipt-dialog.component';

interface CartLine { food: FoodItem; qty: number; }

@Component({
  selector: 'app-pos',
  standalone: true,
  imports: [CommonModule, FormsModule, IconComponent, MoneyPipe, LoadingComponent,
    EmptyStateComponent, SpinnerComponent, ReceiptDialogComponent],
  templateUrl: './pos.component.html',
  styleUrl: './pos.component.scss',
})
export class PosComponent {
  private catalog = inject(CatalogService);
  private orders = inject(OrderService);
  private toast = inject(ToastService);
  private router = inject(Router);

  loading = signal(true);
  placing = signal(false);
  categories = signal<Category[]>([]);
  foods = signal<FoodItem[]>([]);
  activeCategory = signal<number | null>(null);
  search = signal('');

  cart = signal<CartLine[]>([]);
  orderType = signal<'DineIn' | 'Takeaway' | 'Parcel'>('Takeaway');
  paymentMethod = signal<'Cash' | 'Upi' | 'Card' | 'Other'>('Cash');
  discount = signal(0);
  customerName = signal('');
  customerMobile = signal('');
  mobileCartOpen = signal(false);
  receiptOrderId = signal<number | null>(null);

  filteredFoods = computed(() => {
    const s = this.search().trim().toLowerCase();
    return this.foods().filter(f =>
      (this.activeCategory() === null || f.categoryId === this.activeCategory()) &&
      (!s || f.name.toLowerCase().includes(s)));
  });

  subtotal = computed(() => this.cart().reduce((sum, l) => sum + l.food.sellingPrice * l.qty, 0));
  tax = computed(() => this.cart().reduce((sum, l) => sum + (l.food.sellingPrice * l.qty * l.food.taxPercent / 100), 0));
  grandTotal = computed(() => Math.max(0, this.subtotal() + this.tax() - this.discount()));
  cartCount = computed(() => this.cart().reduce((n, l) => n + l.qty, 0));

  constructor() {
    this.catalog.categories(true).subscribe(c => this.categories.set(c));
    this.catalog.posItems().subscribe({
      next: f => { this.foods.set(f); this.loading.set(false); },
      error: () => this.loading.set(false),
    });
  }

  selectCategory(id: number | null) { this.activeCategory.set(id); }

  add(food: FoodItem) {
    this.cart.update(lines => {
      const existing = lines.find(l => l.food.id === food.id);
      if (existing) return lines.map(l => l.food.id === food.id ? { ...l, qty: l.qty + 1 } : l);
      return [...lines, { food, qty: 1 }];
    });
  }
  changeQty(id: number, delta: number) {
    this.cart.update(lines => lines
      .map(l => l.food.id === id ? { ...l, qty: l.qty + delta } : l)
      .filter(l => l.qty > 0));
  }
  qtyOf(id: number): number { return this.cart().find(l => l.food.id === id)?.qty ?? 0; }
  clearCart() { this.cart.set([]); this.discount.set(0); }

  placeOrder() {
    if (!this.cart().length) { this.toast.error('Add at least one item.'); return; }
    this.placing.set(true);
    const body = {
      customerName: this.customerName() || null,
      customerMobile: this.customerMobile() || null,
      orderType: this.orderType(),
      discountAmount: this.discount(),
      paymentMethod: this.paymentMethod(),
      paymentStatus: 'Paid',
      transactionReference: null,
      items: this.cart().map(l => ({ foodItemId: l.food.id, quantity: l.qty })),
    };
    this.orders.create(body).subscribe({
      next: (o: Order) => {
        this.placing.set(false);
        this.toast.success(`Order ${o.orderNumber} placed!`);
        this.receiptOrderId.set(o.id);
        this.clearCart();
        this.customerName.set(''); this.customerMobile.set('');
        this.mobileCartOpen.set(false);
      },
      error: () => this.placing.set(false),
    });
  }

  onReceiptClosed(completed: boolean) {
    this.receiptOrderId.set(null);
  }

  vegDot(f: FoodItem) { return f.isVeg ? 'veg' : 'nonveg'; }
}
